function renderStarterPanel(){$('#startPanel').innerHTML=`<div class="start-panel-card"><div class="start-panel-title"><h3>Starter Templates</h3><span class="note">Every use creates a new copy.</span></div><div class="starter-list">${starterTemplates.map(t=>`<div class="list-card"><div class="list-card-copy"><strong>${escapeHTML(t.name)}</strong><small>${escapeHTML(t.audience||'Healthcare Professional')} · ${escapeHTML(t.product||'PIVYA')}</small></div><div class="list-card-actions"><button type="button" class="tiny-btn primary" data-use-starter="${escapeAttr(t.id)}">Use</button></div></div>`).join('')}</div></div>`;$$('[data-use-starter]').forEach(b=>b.onclick=()=>openCreateFromStarter(b.dataset.useStarter))}
function renderMyEmailsPanel(){const list=state.projects;$('#startPanel').innerHTML=`<div class="start-panel-card"><div class="start-panel-title"><h3>My Emails</h3><span class="note">Saved on this computer.</span></div><div class="project-list">${list.length?list.map(p=>`<div class="list-card"><div class="list-card-copy"><strong>${escapeHTML(p.name)}</strong><small>Updated ${escapeHTML(new Date(p.updatedAt||p.createdAt).toLocaleString())}</small></div><div class="list-card-actions"><button type="button" class="tiny-btn primary" data-open-project="${escapeAttr(p.id)}">Open</button><button type="button" class="tiny-btn" data-rename-project="${escapeAttr(p.id)}">Rename</button><button type="button" class="tiny-btn" data-copy-project="${escapeAttr(p.id)}">Duplicate</button><button type="button" class="tiny-btn" data-download-project="${escapeAttr(p.id)}">Download</button><button type="button" class="tiny-btn danger" data-delete-project="${escapeAttr(p.id)}">Delete</button></div></div>`).join(''):'<div class="empty-list">No working emails yet. Create a new email or use a protected starter template.</div>'}</div></div>`;$$('[data-open-project]').forEach(b=>b.onclick=()=>{loadTemplate(b.dataset.openProject,true);hideStart()});$$('[data-rename-project]').forEach(b=>b.onclick=()=>openRenameProject(b.dataset.renameProject));$$('[data-copy-project]').forEach(b=>b.onclick=()=>{const p=state.projects.find(x=>x.id===b.dataset.copyProject);if(!p)return;state.templateId=p.id;state.docs[p.id]=p.html;state.metadata[p.id]=p.metadata;openSaveAs()});$$('[data-download-project]').forEach(b=>b.onclick=()=>downloadProjectById(b.dataset.downloadProject));$$('[data-delete-project]').forEach(b=>b.onclick=()=>deleteProject(b.dataset.deleteProject))}
