function downloadProjectById(id){const previous=state.templateId,p=state.projects.find(x=>x.id===id);if(!p)return;if(previous===id){saveProjectJSON();return}const payload={app:'Alembic Email Builder',version:7.2,savedAt:new Date().toISOString(),project:p,assets:customAssetsForHTML(p.html),prefs:state.prefs},name=p.name.replace(/[^a-z0-9]+/gi,'_').replace(/^_|_$/g,'')+'.alembic-email';downloadBlob(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),name);toast('Portable project downloaded')}
