function renderProductsPanel(){const custom=state.products.filter(p=>!builtInProducts.some(b=>b.id===p.id));$('#startPanel').innerHTML=`<div class="start-panel-card"><div class="start-panel-title"><h3>Product Profiles</h3><button type="button" class="tiny-btn primary" id="addProductBtn">Add Product</button></div><div class="product-list">${state.products.map(p=>{const fixed=builtInProducts.some(b=>b.id===p.id);return `<div class="list-card"><div class="list-card-copy"><strong>${escapeHTML(p.name)}</strong><small>${fixed?'Built-in profile':'Custom profile'} · Version ${escapeHTML(p.version||'Draft')}</small></div><div class="list-card-actions">${fixed?'<span class="note">Protected</span>':`<button type="button" class="tiny-btn" data-edit-product="${escapeAttr(p.id)}">Edit</button><button type="button" class="tiny-btn danger" data-delete-product="${escapeAttr(p.id)}">Delete</button>`}</div></div>`}).join('')}</div>${!custom.length?'<div class="note" style="margin-top:10px">New products are stored locally and can be used to generate the complete blank pharmacy framework.</div>':''}</div>`;$('#addProductBtn').onclick=()=>openProductEditor();$$('[data-edit-product]').forEach(b=>b.onclick=()=>openProductEditor(b.dataset.editProduct));$$('[data-delete-product]').forEach(b=>b.onclick=()=>deleteProductProfile(b.dataset.deleteProduct))}
function productForm(p={}){return `<div class="modal-form two-col"><label class="modal-field"><span>Product display name</span><input id="pfName" value="${escapeAttr(p.name||'')}"></label><label class="modal-field"><span>Profile version</span><input id="pfVersion" value="${escapeAttr(p.version||new Date().toISOString().slice(0,7))}"></label><label class="modal-field"><span>Brand name</span><input id="pfBrand" value="${escapeAttr(p.brandName||'')}"></label><label class="modal-field"><span>Generic name · lower case</span><input id="pfGeneric" value="${escapeAttr(p.genericName||'')}"></label><label class="modal-field"><span>Registered mark</span><select id="pfMark"><option value="®">®</option><option value="™">™</option><option value="">None</option></select></label><label class="modal-field"><span>Strength</span><input id="pfStrength" value="${escapeAttr(p.strength||'')}" placeholder="Example: 185 mg or 0.2%"></label><label class="modal-field"><span>Dosage form</span><input id="pfDosage" value="${escapeAttr(p.dosageForm||'')}" placeholder="Example: tablets or otic solution"></label><label class="modal-field"><span>Primary color</span><input id="pfPrimary" type="color" value="${escapeAttr(p.primaryColor||'#249647')}"></label><label class="modal-field"><span>Secondary color</span><input id="pfSecondary" type="color" value="${escapeAttr(p.secondaryColor||'#0878C9')}"></label><label class="modal-field wide"><span>Product image · transparent PNG required</span><input id="pfImage" type="file" accept="image/png"><input id="pfImageValue" type="hidden" value="${escapeAttr(p.productImage||'')}"><small id="pfImageStatus">The tool scales and optimizes the PNG automatically. A product image with an opaque background will be rejected.</small></label><label class="modal-field wide"><span>Product website</span><input id="pfProductUrl" type="url" value="${escapeAttr(p.productUrl||'')}"></label><label class="modal-field wide"><span>Prescribing Information URL</span><input id="pfPiUrl" type="url" value="${escapeAttr(p.piUrl||'')}"></label><label class="modal-field wide"><span>Approved indication</span><textarea id="pfIndication">${escapeHTML(p.indication||'')}</textarea></label><label class="modal-field wide"><span>Approved Important Safety Information</span><textarea id="pfIsi">${escapeHTML(p.isi||'')}</textarea></label><label class="modal-field wide"><span>Approved audience/company footer</span><textarea id="pfFooter">${escapeHTML(p.footer||'')}</textarea></label><div class="modal-note wide">The builder checks structure and exact rules. Saving a product profile does not constitute Regulatory or MLR approval.</div><div class="modal-error wide" id="modalError">Product name and generic name are required.</div></div>`}
function openProductEditor(id=''){const p=state.products.find(x=>x.id===id)||{};showModal(id?'Edit Product Profile':'Add Product Profile',productForm(p),`<button type="button" class="secondary-btn" id="cancelModalBtn">Cancel</button><button type="button" class="primary-btn" id="saveProductBtn">Save Product</button>`,'MANUAL PRODUCT SETUP');$('#pfMark').value=p.brandMark||'®';$('#cancelModalBtn').onclick=hideModal;$('#pfImage').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;const status=$('#pfImageStatus');status.textContent='Checking and optimizing product PNG…';try{const out=await optimizeAssetPng(f);if(!out.hasTransparency)throw new Error('Product images must have a transparent background.');$('#pfImageValue').value=out.dataUrl;status.textContent=`Ready: ${out.width}×${out.height} · ${formatBytes(out.bytes)} · transparent background detected`;}catch(err){e.target.value='';status.textContent=err.message||'The product PNG could not be prepared.';}};$('#saveProductBtn').onclick=()=>saveProductProfile(id)}
async function saveProductProfile(existingId=''){const name=$('#pfName').value.trim(),generic=$('#pfGeneric').value.trim().toLowerCase();if(!name||!generic){$('#modalError').style.display='block';return}const strength=$('#pfStrength').value.trim(),dosageForm=$('#pfDosage').value.trim();const p={id:existingId||newId('product'),name,version:$('#pfVersion').value.trim()||new Date().toISOString().slice(0,7),brandName:$('#pfBrand').value.trim().toUpperCase(),genericName:generic,brandMark:$('#pfMark').value,strength,dosageForm,primaryColor:$('#pfPrimary').value,secondaryColor:$('#pfSecondary').value,productImage:$('#pfImageValue').value,productUrl:$('#pfProductUrl').value.trim(),piUrl:$('#pfPiUrl').value.trim(),indication:$('#pfIndication').value.trim(),isi:$('#pfIsi').value.trim(),footer:$('#pfFooter').value.trim(),updatedAt:new Date().toISOString(),approvedClaims:[]};await dbPut('products',p);const i=state.products.findIndex(x=>x.id===p.id);if(i>=0)state.products[i]=p;else state.products.push(p);hideModal();renderProductsPanel();toast('Product profile saved')}
async function deleteProductProfile(id){const p=state.products.find(x=>x.id===id);if(!p||builtInProducts.some(b=>b.id===id)||!confirm(`Delete the product profile “${p.name}”?\n\nExisting emails will remain unchanged.`))return;await dbRemove('products',id);state.products=state.products.filter(x=>x.id!==id);renderProductsPanel();toast('Product profile deleted')}
function svgIcon(name,cls){return `<svg class="icon ${cls||''}" viewBox="0 0 24 24" aria-hidden="true"><use href="#i-${name}"/></svg>`}
function sectionKindIcon(row,label){const text=String(label||'').toLowerCase();const has=s=>text.includes(s);
 if(has('header'))return 'heading';if(has('band')||has('rule')||has('divider')||has('spacer'))return 'minus';
 if(has('hero'))return 'sparkle';if(has('legal name')||has('indication'))return 'pill';
 if(has('safety'))return 'alert';if(has('prescribing'))return 'book';if(has('reference'))return 'list-ordered';
 if(has('footer')&&!has('social'))return 'scale';if(has('social')||has('company'))return 'share';
 if(has('order'))return 'truck';if(has('saving'))return 'tag';if(has('storage'))return 'thermometer';
 if(has('dosing'))return 'clock';if(has('resistance'))return 'shield-alert';if(has('targeting'))return 'target';
 if(has('patient'))return 'user';if(has('data')||has('chart')||has('trial'))return 'chart';
 if(has('call to action')||has('cta'))return 'arrow-right-circle';if(has('note')||has('qualifier'))return 'info';
 if(has('pack'))return 'box';if(has('key point')||has('card'))return 'cards-3';
 if(has('column'))return 'columns-2';if(has('image'))return 'image';
 if(row&&row.querySelector&&row.querySelector('img'))return 'image';
 return 'text'}
function buildBlockGrid(){
 const grid=$('#blockGrid'); grid.innerHTML='';
 const visible=blockDefs.filter(b=>!b.product||b.product===currentProduct()),groups=[...new Set(visible.map(b=>b.group||'Core content'))];
 groups.forEach(group=>{
   const heading=document.createElement('div');heading.className='block-group-title';heading.textContent=group;grid.appendChild(heading);
   visible.filter(b=>(b.group||'Core content')===group).forEach(b=>{
     const btn=document.createElement('button');btn.className='block-card'+(b.pharmacy&&state.audience==='Pharmacy'?' recommended':'');btn.type='button';btn.dataset.block=b.id;
     btn.innerHTML=`<div class="block-icon">${svgIcon(b.icon)}</div><div class="block-name">${b.name}</div><div class="block-desc">${b.desc}</div>${b.pharmacy&&state.audience==='Pharmacy'?'<span class="recommend-pill">Recommended</span>':''}`;
     btn.addEventListener('click',()=>addBlock(b.id));grid.appendChild(btn);
   });
 });
 $('#audienceHint').textContent=state.audience==='Pharmacy'?'Pharmacy mode: ordering information and patient-access blocks are highlighted.':'HCP mode: clinical, dosing, evidence and patient-access blocks are available. Switch to Pharmacy to highlight stocking tools.';
}
