 $('#assetBaseUrl').value=state.prefs.assetBaseUrl||''; $('#assetBaseUrl').addEventListener('input',e=>{state.prefs.assetBaseUrl=e.target.value.trim();storage.setItem(PREF_KEY,JSON.stringify(state.prefs));renderAssetUrlMap();runQA(false)});
 window.addEventListener('beforeunload',saveCurrent);
