async function buildReferencePdf(){const previous={mode:state.mode,width:state.width};if(state.mode!=='desktop'||state.width!==720){setView('desktop',720);await waitForLayout()}try{const rendered=await renderEmailCanvas(),pages=[],slice=Math.round(850*rendered.density);for(let y=0;y<rendered.height;y+=slice){const h=Math.min(slice,rendered.height-y),c=document.createElement('canvas');c.width=rendered.width;c.height=h;const pageCtx=c.getContext('2d');if(!pageCtx)throw new Error('This browser could not create a PDF page.');pageCtx.fillStyle='#FFFFFF';pageCtx.fillRect(0,0,c.width,c.height);pageCtx.drawImage(rendered.canvas,0,y,rendered.width,h,0,0,rendered.width,h);const encoded=c.toDataURL('image/jpeg',.9).split(',')[1];if(!encoded)throw new Error('This browser could not encode the PDF page.');pages.push({width:c.width,height:c.height,bytes:base64Bytes(encoded)})}return makePdf(pages)}finally{if(previous.mode!=='desktop'||previous.width!==720){setView(previous.mode,previous.width);await waitForLayout()}}}
function wrapReferenceText(ctx,text,maxWidth){const words=String(text||'').replace(/\s+/g,' ').trim().split(' '),lines=[];let line='';for(const word of words){const test=line?line+' '+word:word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);return lines}
function buildTextReferencePdf(){const doc=frameDoc(),meta=state.metadata[state.templateId]||{},width=1100,margin=70,lineHeight=27,probe=document.createElement('canvas'),pctx=probe.getContext('2d');if(!pctx)throw new Error('This browser could not create the reference fallback.');pctx.font='18px Arial';const paragraphs=(doc?.body?.innerText||'').split(/\n+/).map(s=>s.trim()).filter(Boolean),lines=[];lines.push(meta.subject||templateById(state.templateId)?.name||'Email Reference','');paragraphs.forEach(p=>{lines.push(...wrapReferenceText(pctx,p,width-margin*2),'')});const height=Math.max(900,margin+lines.length*lineHeight+margin),canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');if(!ctx)throw new Error('This browser could not create the reference fallback.');ctx.fillStyle='#FFFFFF';ctx.fillRect(0,0,width,height);ctx.fillStyle='#173F34';ctx.font='bold 28px Arial';ctx.fillText(lines.shift()||'Email Reference',margin,margin);ctx.fillStyle='#253449';ctx.font='18px Arial';let y=margin+48;for(const line of lines){if(line)ctx.fillText(line,margin,y);y+=lineHeight}const pages=[],slice=1400;for(let top=0;top<height;top+=slice){const h=Math.min(slice,height-top),c=document.createElement('canvas');c.width=width;c.height=h;const pageCtx=c.getContext('2d');pageCtx.fillStyle='#FFFFFF';pageCtx.fillRect(0,0,width,h);pageCtx.drawImage(canvas,0,top,width,h,0,0,width,h);pages.push({width,height:h,bytes:base64Bytes(c.toDataURL('image/jpeg',.9).split(',')[1])})}return makePdf(pages)}
async function exportDeploymentPackage(){saveCurrent();const qa=runQA(false),usage=referencedAssetUsage(),missing=usage.filter(u=>!u.asset||!assetData[u.src]);if(missing.length){showTab('qa');alert('The Send Folder was not created because these images are missing:\n\n'+missing.map(x=>x.src).join('\n'));return}if(qa.errors){showTab('qa');alert(`The Send Folder was not created because Preflight found ${qa.errors} blocking issue(s). Fix the red items, then click Create Send Folder again.`);return}toast('Creating Send Folder…');try{const t=templateById(state.templateId),baseName=(t?.filename||state.templateId+'.html').replace(/\.html$/i,'').replace(/[^a-z0-9_-]+/gi,'_'),root=baseName+'_SEND_FOLDER',files=[],payload=buildDeploymentPayload();files.push({name:`${root}/EMAIL.html`,data:payload.html});usage.forEach(u=>files.push({name:`${root}/images/${u.src.split('/').pop()}`,data:base64Bytes(assetData[u.src])}));payload.uploads.forEach(u=>files.push({name:`${root}/images/${u.name}`,data:u.data}));let pdf;try{pdf=await buildReferencePdf()}catch(pdfError){pdf=buildTextReferencePdf();files.push({name:`${root}/PDF_REFERENCE_NOTE.txt`,data:'The visual PDF renderer was unavailable in the browser that created this package. EMAIL_REFERENCE.pdf contains the complete email text. Open EMAIL.html in a browser for the authoritative visual reference.\r\n'})}files.push({name:`${root}/EMAIL_REFERENCE.pdf`,data:pdf});files.push({name:`${root}/READ_ME_FIRST.txt`,data:buildPackageReadme()});files.push({name:`${root}/CAMPAIGN_DETAILS.txt`,data:buildCampaignDetails()});downloadBlob(makeZip(files),root+'.zip');toast('Send Folder created')}catch(err){const message=err instanceof Error&&err.message?err.message:'An unexpected browser error occurred.';alert('The Send Folder could not be created. '+message);}}
function serializeWorkingHTML(){const doc=frameDoc();if(!doc)return state.docs[state.templateId];const selected=$('[data-builder-selected="true"]',doc);const sec=$('[data-builder-section-selected="true"]',doc);if(selected)delete selected.dataset.builderSelected;if(sec)delete sec.dataset.builderSectionSelected;const preview=doc.getElementById('pivya-builder-preview-css');if(preview)preview.remove();const html='<!doctype html>\n'+doc.documentElement.outerHTML;injectPreviewCSS(doc);if(selected)selected.dataset.builderSelected='true';if(sec)sec.dataset.builderSectionSelected='true';return html;}
function queueProjectSave(project){clearTimeout(state.saveTimer);state.saveTimer=setTimeout(()=>dbPut('projects',project).catch(()=>toast('Local save could not be completed')),180)}
function saveCurrent(show=false){if(!state.templateId)return;const project=state.projects.find(p=>p.id===state.templateId);if(!project){if(show)openCreateFromStarter(state.templateId);return}state.docs[state.templateId]=serializeWorkingHTML();project.html=state.docs[state.templateId];project.metadata=JSON.parse(JSON.stringify(state.metadata[state.templateId]||{}));project.updatedAt=new Date().toISOString();queueProjectSave(project);if(show)toast('Working email saved');$('#saveStatus').textContent='Saved locally';}
function saveMeta(){if(!state.templateId)return;const project=state.projects.find(p=>p.id===state.templateId);if(project){project.metadata=JSON.parse(JSON.stringify(state.metadata[state.templateId]||{}));project.updatedAt=new Date().toISOString();queueProjectSave(project)}$('#saveStatus').textContent='Saved locally'}
function commitChange(rerender=true){tagSections(frameDoc());saveCurrent();if(rerender){renderSections();renderInspector()}resizeIframe();$('#saveStatus').textContent='Saved locally'}
function pushHistory(){if(state.suppressHistory)return;const snap=serializeWorkingHTML();if(state.history[state.history.length-1]!==snap)state.history.push(snap);if(state.history.length>40)state.history.shift();state.future=[];updateUndoButtons()}
function undo(){if(!state.history.length)return;state.future.push(serializeWorkingHTML());const prev=state.history.pop();restoreSnapshot(prev);updateUndoButtons()}
function redo(){if(!state.future.length)return;state.history.push(serializeWorkingHTML());const next=state.future.pop();restoreSnapshot(next);updateUndoButtons()}
function restoreSnapshot(html){state.suppressHistory=true;state.docs[state.templateId]=html;const f=$('#emailFrame');f.srcdoc=html;f.onload=()=>{prepareFrame();renderSections();renderInspector();saveCurrent();state.suppressHistory=false;resizeIframe()}}
function updateUndoButtons(){$('#undoBtn').disabled=!state.history.length;$('#redoBtn').disabled=!state.future.length}
function resetTemplate(){const p=state.projects.find(x=>x.id===state.templateId);if(!p){openCreateFromStarter(state.templateId);return}if(!confirm('Restore this working email to the point where it was created? Your current edits will be removed.'))return;state.docs[p.id]=p.startingHtml||p.html;state.metadata[p.id]=JSON.parse(JSON.stringify(p.startingMetadata||p.metadata||{}));p.html=state.docs[p.id];p.metadata=state.metadata[p.id];p.updatedAt=new Date().toISOString();dbPut('projects',p);loadTemplate(p.id,false);toast('Restored from starter')}
function exportHTML(){saveCurrent();const usage=referencedAssetUsage(),unresolved=usage.filter(u=>!/^https:\/\//i.test(resolveProductionUrl(u.src))),embedded=$$('img',frameDoc()).filter(img=>/^data:/i.test(img.getAttribute('src')||''));if(unresolved.length||embedded.length){alert(`Production HTML was not exported because ${unresolved.length+embedded.length} image(s) are not yet hosted on public HTTPS URLs.\n\nCreate the Send Folder, upload its images in the email platform, then use the platform's HTTPS image URLs.`);showTab('qa');return}const qa=runQA(false);if(qa.errors){showTab('qa');alert(`Production HTML was not exported because Preflight found ${qa.errors} blocking issue(s). Fix the red items and try again.`);return}const html=cleanExportHTML(true);const t=templateById(state.templateId);const name=((t?.filename||'Alembic_Email.html').replace(/\.html$/i,'')+'_PRODUCTION.html');downloadBlob(new Blob([html],{type:'text/html'}),name);toast('Production HTML exported')}
function saveProjectJSON(){saveCurrent();const p=state.projects.find(x=>x.id===state.templateId);if(!p)return;const html=serializeWorkingHTML(),payload={app:'Alembic Email Builder',version:7.2,savedAt:new Date().toISOString(),project:Object.assign({},p,{html,metadata:state.metadata[p.id]}),assets:customAssetsForHTML(html),prefs:state.prefs};const name=p.name.replace(/[^a-z0-9]+/gi,'_').replace(/^_|_$/g,'')+'.alembic-email';downloadBlob(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),name);toast('Portable project downloaded')}
function importProjectJSON(e){const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=async()=>{try{const payload=JSON.parse(r.result);let source;if(payload.project?.html)source=payload.project;else if(payload.docs&&payload.metadata){const first=Object.keys(payload.docs)[0];source={name:f.name.replace(/\.(json|alembic-email)$/i,''),html:payload.docs[first],metadata:payload.metadata[first]||{},sourceTemplateId:first,product:templateById(first)?.product||'general'}}else throw new Error('Invalid project');if(Array.isArray(payload.assets)){for(const a of payload.assets){if(!a?.id||!a?.data||!a?.path)continue;const existing=state.customAssets.find(x=>x.id===a.id);if(!existing){await dbPut('assets',a);state.customAssets.push(a)}}refreshAssetRegistry();populateAssetFilters()}if(payload.prefs){state.prefs=Object.assign(state.prefs,payload.prefs);storage.setItem(PREF_KEY,JSON.stringify(state.prefs))}await createProject({name:(source.name||'Imported Email')+' · Imported',html:migrateLegacyAssetPaths(source.html),startingHtml:migrateLegacyAssetPaths(source.startingHtml||source.html),metadata:source.metadata||{},startingMetadata:source.startingMetadata||source.metadata||{},sourceTemplateId:source.sourceTemplateId||'',product:source.product||'general',profileId:source.profileId||source.product||'general',profileVersion:source.profileVersion||'',filename:source.filename||'Alembic_Imported_Email.html',brandName:source.brandName,genericName:source.genericName,brandMark:source.brandMark});toast('Project and reusable assets opened as a new email')}catch{alert('That file is not a valid Alembic Email Builder project.')}e.target.value=''};r.readAsText(f)}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000)}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.remove('show'),1800)}
function escapeHTML(s){return String(s??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}
function escapeAttr(s){return escapeHTML(s).replace(/"/g,'&quot;')}

